function escAdmin(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));}document.addEventListener('DOMContentLoaded',async()=>{const el=document.getElementById('reviews-real');try{const rows=await apiFetch('/operacoes/admin/avaliacoes');el.innerHTML=rows.length?rows.map(a=>`<tr><td>${escAdmin(a.produto_nome)}</td><td>${escAdmin(a.nome_autor)}</td><td>${Array.from({length:5},(_,i)=>`<svg viewBox="0 0 24 24" width="15" height="15" fill="${i<a.estrelas?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"></path></svg>`).join('')}</td><td>${escAdmin(a.comentario||'')}</td><td><button onclick="moderar(${a.id},${!a.aprovado})">${a.aprovado?'Rejeitar':'Aprovar'}</button></td></tr>`).join(''):'<tr><td colspan="5">Ainda não existem avaliações.</td></tr>'}catch(e){el.innerHTML=`<tr><td colspan="5">${escAdmin(e.message)}</td></tr>`}});async function moderar(id,aprovado){try{await apiFetch('/operacoes/admin/avaliacoes/'+id,{method:'PUT',body:JSON.stringify({aprovado})});location.reload()}catch(e){alert(e.message)}}
